// AssertTxWithRetryContract runs every generated check against every declared subject.
//
//	Subjects: declare each with TxWithRetrySubject
//	Extend:   TxWithRetryOnBegin, TxWithRetryOnCommit, TxWithRetryOnRollback
//	Drop:     TxWithRetryWithout, by the path each check reports under
//	Unseeded: every check here runs against a fresh subject, because
//	          no method here is classified as a write.
//	          A read over an empty subject cannot tell a miss from a bug;
//	          TxWithRetrySeed is what closes it.
func AssertTxWithRetryContract(t *testing.T, opts ...TxWithRetryOption) {
	t.Helper()
	cfg := newTxWithRetryConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertTxWithRetryContract was given no subject; declare one with " +
			"TxWithRetrySubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("TxWithRetryWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runTxWithRetryChecks(t, cfg, s.name, s.factory, nil)
	}
}

// runTxWithRetryChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runTxWithRetryChecks(
	t *testing.T,
	cfg *txwithretryConfig,
	label string,
	factory func() txwithretry.TxWithRetry,
	wrap func(tb testing.TB, subject txwithretry.TxWithRetry) txwithretry.TxWithRetry,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run(txWithRetryBegin, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onBegin {
				cfg.run(t, string(suite.MethodID(txWithRetryBegin, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		t.Run(txWithRetryCommit, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onCommit {
				cfg.run(t, string(suite.MethodID(txWithRetryCommit, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		t.Run(txWithRetryRollback, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onRollback {
				cfg.run(t, string(suite.MethodID(txWithRetryRollback, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through TxWithRetryWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

